    n = len(arr)
    # Create a 2D array to store the minimum number of changes for each possible subarray
    dp = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 0
    for l in range(1, n):
        for i in range(n - l):
            j = i + l
            if arr[i] == arr[j]:
                dp[i][j] = dp[i+1][j-1]
